package com.atlasiq.governance;
import jakarta.enterprise.context.ApplicationScoped;import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.util.stream.Stream;
@ApplicationScoped public class AdrParser {private static final Pattern ID=Pattern.compile("(?im)^adr-id:\\s*(.+)$"),STATUS=Pattern.compile("(?im)^status:\\s*(.+)$"),QIR=Pattern.compile("(?im)^qir:\\s*(.+)$"),POL=Pattern.compile("(?im)^policies:\\s*(.+)$");
 public List<ArchitectureDecisionRecord> parse(Path root){List<ArchitectureDecisionRecord> out=new ArrayList<>();Path dir=root.resolve("docs/adr");if(!Files.isDirectory(dir))return out;try(Stream<Path>s=Files.list(dir)){s.filter(p->p.toString().endsWith(".md")).sorted().forEach(p->{try{String x=Files.readString(p);String title=x.lines().filter(l->l.startsWith("# ")).findFirst().orElse("# "+p.getFileName()).substring(2);String id=find(ID,x,p.getFileName().toString().replace(".md",""));out.add(new ArchitectureDecisionRecord(id,title,find(STATUS,x,"accepted"),x,split(find(QIR,x,"")),split(find(POL,x,"")),root.relativize(p).toString()));}catch(Exception ignored){}});}catch(Exception e){throw new IllegalStateException(e);}return List.copyOf(out);}
 private String find(Pattern p,String x,String d){Matcher m=p.matcher(x);return m.find()?m.group(1).trim():d;}private List<String> split(String x){return x.isBlank()?List.of():Arrays.stream(x.split(",")).map(String::trim).filter(v->!v.isBlank()).toList();}
}